import { useCallback } from 'react';
import { getExtRouter } from './internal/getExtRouter';
import { useRoutesConfig } from './internal/useRoutesConfig';
/**
 * Stores the original route descriptor for each AppRoute created by createAppRoute,
 * enabling navigateToAppRoute to resolve an AppRoute back to its key + params
 */
const routeDescriptors = new WeakMap();
/**
 * Returns methods for navigating to full-page routes.
 *
 * @see https://docs.stripe.com/stripe-apps/routing
 */
export function useNavigation() {
    const router = getExtRouter();
    const config = useRoutesConfig();
    const navigateToAppRoute = useCallback((routeOrAppRoute, options) => {
        const route = `key` in routeOrAppRoute
            ? routeOrAppRoute
            : routeDescriptors.get(routeOrAppRoute);
        if (!route)
            return;
        router.setRoute(config, route, options);
    }, [router, config]);
    const createAppRoute = useCallback((routeConfig) => {
        // NB: removed for SAILEXTENSIBILITY-1668
        // const {searchParams} = routeConfig;
        const glob = router.createPathSegments(config, routeConfig);
        const route = {
            name: 'fullPageGlob',
            params: {
                glob,
                // NB: removed for SAILEXTENSIBILITY-1668
                // searchParams
            },
        };
        routeDescriptors.set(route, routeConfig);
        return route;
    }, [config, router]);
    return { navigateToAppRoute, createAppRoute };
}
